def write(p,x):p.parent.mkdir(exist_ok=True,parents=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def copy(p,name):shutil.copyfile(p,S/name);return (S/name).relative_to(P).as_posix()
def span(path,a,b,label):return dict(path=path,start_line=a,end_line=b,label=label)
def prepare_source(pid,bodyfile):
 m=next(x for x in manifest if x['problem_id']==pid); old=R/'editable-corpus';item=(old/m['item_path']).read_text(encoding='utf-8-sig');pre=item.split(r'\begin{document}')[0];(S/(pid+'-preamble.tex')).write_text(pre,encoding='utf-8');body=copy(old/'sources'/pid/bodyfile,pid+'-source.tex')
 bib=item[item.index(r'\begin{thebibliography}'):item.index(r'\end{thebibliography}')+len(r'\end{thebibliography}')];(S/(pid+'-bibliography.tex')).write_text(bib+'\n',encoding='utf-8');licfile='rights-facts.json' if pid=='2413' else 'license-notice.txt';lic=copy(old/'sources'/pid/licfile,pid+'-'+licfile)
 return m,body,span((S/(pid+'-preamble.tex')).relative_to(P).as_posix(),1,len(pre.splitlines()),'Existing compiled standalone preamble reused'),lic,(S/(pid+'-bibliography.tex')).relative_to(P).as_posix()
def make(pid,data,tid,title,label,statement,proof,context,obs,reason,diff,prereq):
 m,body,pre,lic,bib=data
 t=dict(schema_version=2,selected_by='AGP-materials',task_id=tid,problem_id=None,revision='r001',source_id=m['source_id'],source_version=m['source_version'],source_url=m['source_url'],claim_key=m['source_id']+':'+label,title=title,authors=[x.strip() for x in m['author'].split(';')],route='probability',license={'name':'CC BY 4.0','evidence_path':lic,'version_url':m['source_url']},statement_spans=[span(body,a,b,'Selected author claim '+label) for a,b in statement],proof_spans=[span(body,a,b,'Complete author argument or retained local supporting proof') for a,b in proof],context_spans=[span(body,a,b,'Original definitions and contextual statements') for a,b in context],standard_prerequisites=[{'name':prereq,'use':'Standard cited foundations only; all selected local constructions and proof estimates remain in source ranges.'}],core_obligations=obs,proof_roadmap=[{'step':x,'spans':[span(body,a,b,'Author proof') for a,b in proof]} for x in obs],difficulty_level='H2',difficulty_reason=reason,dedup={'conclusion':'focused_semantic_uniqueness_supported','compared_ids':[pid]+(['152964'] if pid=='2413' else []),'compared':[{'problem_id':pid,'difference':diff}],'scope':'Focused same-source lookup in local manifest, preparation worklist and retired claims. Original counted claim and selected continuation claims distinguished; supporting lemmas not separately counted.'},review_paths=[],review_protocol='material-preparation-v1',status='ready_for_assembly',issues=[],ready_blockers=[],material_preparation={'pairing':'Author statement and corresponding proof headings/endings matched; complete local proof ranges and original dependencies retained.','scope':'No independent mathematical certification or invented review. Original source wording retained.'})
 bodysp=[dict(role=role,**s) for role in ['context','statement','proof'] for s in t[role+'_spans']]
 t['assembly']=dict(engine='xelatex',allow_shell_escape=False,document_class='article',preamble_spans=[pre],body_spans=bodysp,asset_paths=[],bibliography_paths=[bib],bibliography_backend='none',external_references=[],editorial_notes=['Only the selected claim is counted. Other author results are retained as context or local proof support; no mathematical content has been rewritten.'])
 write(O/tid/'task.json',t);print(tid)
 return t
